# Surah Al-Jathiya (chapter 45) — part 2: ayat 15-26 (IDs 4488-4499)
SURAH = 45

ENTRIES = {
4488: (
"جو نیکی کرے وہ اس کے لیے ہے — اور جو برائی کرے وہ اسی پر ہے — پھر تم اپنے رب کی طرف لوٹائے جاؤ گے",
"""۱۔ اعمال کا بدلہ — من عمل صالحاً فلنفسه؛ من أساء فعلیها؛ ثم إلی ربکم ترجعون۔
۲۔ ’’مَنْ عَمِلَ صَالِحًا فَلِنَفْسِهِ وَمَنْ أَسَاءَ فَعَلَيْهَا ثُمَّ إِلَىٰ رَبِّكُمْ تُرْجَعُونَ‘‘ — جو نیکی کرے وہ اس کے لیے ہے — اور جو برائی کرے وہ اسی پر ہے — پھر تم اپنے رب کی طرف لوٹائے جاؤ گے — یعنی جو نیکی کرے وہ اس کے لیے ہے اور جو برائی کرے وہ اسی پر ہے پھر تم اپنے رب کی طرف لوٹائے جاؤ گے۔
۳۔ عملی سبق: نیک عمل کرو؛ ظلم سے بچو؛ اللہ سے ڈرو۔"""
),
4489: (
"اور بے شک ہم نے بنی اسرائیل کو کتاب حکومت اور نبوت عطا کی — اور ہم نے انہیں پاکیزہ رزق دیا — اور ہم نے انہیں جہانوں پر فضیلت دی",
"""۱۔ بنی اسرائیل کی نعمتیں — و لقد آتینا بنی إسرائیل الکتاب و الحکم و النبوۃ؛ و رزقناهم من الطیبات؛ و فضلناهم علی العالمین۔
۲۔ ’’وَلَقَدْ آتَيْنَا بَنِي إِسْرَائِيلَ الْكِتَابَ وَالْحُكْمَ وَالنُّبُوَّۃَ وَرَزَقْنَاهُم مِّنَ الطَّيِّبَاتِ وَفَضَّلْنَاهُمْ عَلَى الْعَالَمِينَ‘‘ — اور بے شک ہم نے بنی اسرائیل کو کتاب حکومت اور نبوت عطا کی — اور ہم نے انہیں پاکیزہ رزق دیا — اور ہم نے انہیں جہانوں پر فضیلت دی — یعنی اور بے شک ہم نے بنی اسرائیل کو کتاب حکومت اور نبوت عطا کی اور ہم نے انہیں پاکیزہ رزق دیا اور ہم نے انہیں جہانوں پر فضیلت دی۔
۳۔ عملی سبق: اللہ کی نعمتوں کا شکر کرو؛ اللہ سے ڈرو۔"""
),
4490: (
"اور ہم نے انہیں اس معاملے میں روشن دلیلیں دیں — تو انہوں نے اختلاف نہیں کیا مگر اس کے بعد کہ ان کے پاس علم آ چکا تھا — آپس کی ضد کی بنا پر — بے شک تمہارا رب قیامت کے دن ان کے درمیان فیصلہ کرے گا اس چیز میں جس میں وہ اختلاف کرتے ہیں",
"""۱۔ اختلاف کا سبب — و آتیناهم بینات من الأمر؛ فما اختلفوا إلا من بعد ما جاءهم العلم بغیاً بینهم؛ إن ربک یقضی بینهم یوم القیامۃ فيما کانوا فيه یختلفون۔
۲۔ ’’وَآتَيْنَاهُم بَيِّنَاتٍ مِّنَ الْأَمْرِ فَمَا اخْتَلَفُوا إِلَّا مِن بَعْدِ مَا جَاءَهُمُ الْعِلْمُ بَغْيًا بَيْنَهُمْ إِنَّ رَبَّكَ يَقْضِي بَيْنَهُمْ يَوْمَ الْقِيَامَۃِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ‘‘ — اور ہم نے انہیں اس معاملے میں روشن دلیلیں دیں — تو انہوں نے اختلاف نہیں کیا مگر اس کے بعد کہ ان کے پاس علم آ چکا تھا — آپس کی ضد کی بنا پر — بے شک تمہارا رب قیامت کے دن ان کے درمیان فیصلہ کرے گا اس چیز میں جس میں وہ اختلاف کرتے ہیں — یعنی اور ہم نے انہیں اس معاملے میں روشن دلیلیں دیں تو انہوں نے اختلاف نہیں کیا مگر اس کے بعد کہ ان کے پاس علم آ چکا تھا آپس کی ضد کی بنا پر بے شک تمہارا رب قیامت کے دن ان کے درمیان فیصلہ کرے گا اس چیز میں جس میں وہ اختلاف کرتے ہیں۔
۳۔ عملی سبق: علم کے بعد بھی ضد نہ کرو؛ اللہ سے ڈرو۔"""
),
4491: (
"پھر ہم نے تجھے اس معاملے میں ایک طریقہ (شریعت) پر قرار دیا — پس تو اس کی پیروی کر — اور ان لوگوں کی خواہشوں کی پیروی نہ کر جو نہیں جانتے",
"""۱۔ شریعت کی پیروی — ثم جعلناک علی شریعۃ من الأمر؛ فاتبعها و لا تتبع أهواء الذین لا یعلمون۔
۲۔ ’’ثُمَّ جَعَلْنَاكَ عَلَىٰ شَرِيعَۃٍ مِّنَ الْأَمْرِ فَاتَّبِعْهَا وَلَا تَتَّبِعْ أَهْوَاءَ الَّذِينَ لَا يَعْلَمُونَ‘‘ — پھر ہم نے تجھے اس معاملے میں ایک طریقہ (شریعت) پر قرار دیا — پس تو اس کی پیروی کر — اور ان لوگوں کی خواہشوں کی پیروی نہ کر جو نہیں جانتے — یعنی پھر ہم نے تجھے اس معاملے میں ایک طریقہ (شریعت) پر قرار دیا پس تو اس کی پیروی کر اور ان لوگوں کی خواہشوں کی پیروی نہ کر جو نہیں جانتے۔
۳۔ عملی سبق: شریعت کی پیروی کرو؛ بے علم لوگوں کی خواہشیں نہ مانو؛ اللہ سے ڈرو۔"""
),
4492: (
"بے شک وہ اللہ کے مقابلے میں تمہیں کچھ فائدہ نہ دے سکیں گے — اور بے شک ظالم ایک دوسرے کے دوست ہیں — اور اللہ متقیوں کا دوست ہے",
"""۱۔ ظالمین اور متقین — إنهم لن یغنوا عنک من اللہ شیئًا؛ و إن الظالمین بعضهم أولیاء بعض؛ و اللہ ولی المتقین۔
۲۔ ’’إِنَّهُمْ لَن يُغْنُوا عَنكَ مِنَ اللَّهِ شَيْئًا وَإِنَّ الظَّالِمِينَ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ وَاللَّهُ وَلِيُّ الْمُتَّقِينَ‘‘ — بے شک وہ اللہ کے مقابلے میں تمہیں کچھ فائدہ نہ دے سکیں گے — اور بے شک ظالم ایک دوسرے کے دوست ہیں — اور اللہ متقیوں کا دوست ہے — یعنی بے شک وہ اللہ کے مقابلے میں تمہیں کچھ فائدہ نہ دے سکیں گے اور بے شک ظالم ایک دوسرے کے دوست ہیں اور اللہ متقیوں کا دوست ہے۔
۳۔ عملی سبق: اللہ کو دوست بناؤ؛ ظالموں کی دوستی چھوڑو؛ اللہ سے ڈرو۔"""
),
4493: (
"یہ لوگوں کے لیے بصیرتیں ہیں — اور یقین رکھنے والوں کے لیے ہدایت اور رحمت",
"""۱۔ قرآن کا نور — ہذا بصائر للناس؛ و هدى و رحمۃ لقوم یوقنون۔
۲۔ ’’هَٰذَا بَصَائِرُ لِلنَّاسِ وَهُدًى وَرَحْمَۃٌ لِّقَوْمٍ يُوقِنُونَ‘‘ — یہ لوگوں کے لیے بصیرتیں ہیں — اور یقین رکھنے والوں کے لیے ہدایت اور رحمت — یعنی یہ لوگوں کے لیے بصیرتیں ہیں اور یقین رکھنے والوں کے لیے ہدایت اور رحمت۔
۳۔ عملی سبق: قرآن کو بصیرت مانو؛ یقین حاصل کرو؛ اللہ سے ڈرو۔"""
),
4494: (
"یا وہ لوگ جنہوں نے برائیاں کمائیں کیا یہ سمجھتے ہیں کہ ہم انہیں اُن لوگوں جیسا بنا دیں گے جو ایمان لائے اور نیک عمل کیے — کہ ان کی زندگی اور موت یکساں ہو — بری بات ہے جو وہ حکم کرتے ہیں",
"""۱۔ برابر کا حکم؟ — أم حسب الذین اجترحوا السیئات أن نجعلهم کالذین آمنوا و عملوا الصالحات؛ سواءً محیاهم و مماتهم؛ ساء ما یحکمون۔
۲۔ ’’أَمْ حَسِبَ الَّذِينَ اجْتَرَحُوا السَّيِّئَاتِ أَن نَّجْعَلَهُمْ كَالَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ سَوَاءً مَّحْيَاهُمْ وَمَمَاتُهُمْ سَاءَ مَا يَحْكُمُونَ‘‘ — یا وہ لوگ جنہوں نے برائیاں کمائیں کیا یہ سمجھتے ہیں کہ ہم انہیں اُن لوگوں جیسا بنا دیں گے جو ایمان لائے اور نیک عمل کیے — کہ ان کی زندگی اور موت یکساں ہو — بری بات ہے جو وہ حکم کرتے ہیں — یعنی یا وہ لوگ جنہوں نے برائیاں کمائیں کیا یہ سمجھتے ہیں کہ ہم انہیں اُن لوگوں جیسا بنا دیں گے جو ایمان لائے اور نیک عمل کیے کہ ان کی زندگی اور موت یکساں ہو بری بات ہے جو وہ حکم کرتے ہیں۔
۳۔ عملی سبق: اچھا عمل کرو؛ غلط فیصلے سے بچو؛ اللہ سے ڈرو۔"""
),
4495: (
"اور اللہ نے آسمانوں اور زمین کو حق کے ساتھ پیدا کیا — اور تاکہ ہر جان کو اس کی کمائی کا بدلہ دیا جائے — اور ان پر ظلم نہیں کیا جائے گا",
"""۱۔ تخلیق بالحق — و خلق اللہ السماوات و الأرض بالحق؛ و لتجزی کل نفس بما کسبت؛ و هم لا یظلمون۔
۲۔ ’’وَخَلَقَ اللَّهُ السَّمَاوَاتِ وَالْأَرْضَ بِالْحَقِّ وَلِتُجْزَىٰ كُلُّ نَفْسٍ بِمَا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ‘‘ — اور اللہ نے آسمانوں اور زمین کو حق کے ساتھ پیدا کیا — اور تاکہ ہر جان کو اس کی کمائی کا بدلہ دیا جائے — اور ان پر ظلم نہیں کیا جائے گا — یعنی اور اللہ نے آسمانوں اور زمین کو حق کے ساتھ پیدا کیا اور تاکہ ہر جان کو اس کی کمائی کا بدلہ دیا جائے اور ان پر ظلم نہیں کیا جائے گا۔
۳۔ عملی سبق: حق پر ایمان رکھو؛ نیک عمل کرو؛ اللہ سے ڈرو۔"""
),
4496: (
"کیا تو نے دیکھا جس نے اپنی خواہش کو اپنا معبود بنا لیا — اور اللہ نے علم کی بنا پر اسے گمراہ کر دیا — اور اس کے کان اور دل پر مہر لگا دی — اور اس کی آنکھ پر پردہ ڈال دیا — پھر اللہ کے بعد اسے کون ہدایت دے گا — کیا تم نصیحت نہیں پکڑتے",
"""۱۔ خواہش پرست — أفرأیت من اتخذ إلہه هواه؛ و أضله اللہ علی علم؛ و ختم علی سمعه و قلبه؛ و جعل علی بصره غشاوۃ؛ فمن یهدیه من بعد اللہ؛ أفلا تذکرون۔
۲۔ ’’أَفَرَأَيْتَ مَنِ اتَّخَذَ إِلَٰهَهُ هَوَاهُ وَأَضَلَّهُ اللَّهُ عَلَىٰ عِلْمٍ وَخَتَمَ عَلَىٰ سَمْعِهِ وَقَلْبِهِ وَجَعَلَ عَلَىٰ بَصَرِهِ غِشَاوَۃً فَمَن يَهْدِيهِ مِن بَعْدِ اللَّهِ أَفَلَا تَذَكَّرُونَ‘‘ — کیا تو نے دیکھا جس نے اپنی خواہش کو اپنا معبود بنا لیا — اور اللہ نے علم کی بنا پر اسے گمراہ کر دیا — اور اس کے کان اور دل پر مہر لگا دی — اور اس کی آنکھ پر پردہ ڈال دیا — پھر اللہ کے بعد اسے کون ہدایت دے گا — کیا تم نصیحت نہیں پکڑتے — یعنی کیا تو نے دیکھا جس نے اپنی خواہش کو اپنا معبود بنا لیا اور اللہ نے علم کی بنا پر اسے گمراہ کر دیا اور اس کے کان اور دل پر مہر لگا دی اور اس کی آنکھ پر پردہ ڈال دیا پھر اللہ کے بعد اسے کون ہدایت دے گا کیا تم نصیحت نہیں پکڑتے۔
۳۔ عملی سبق: خواہش کو معبود نہ بناؤ؛ اللہ سے ڈرو۔"""
),
4497: (
"اور وہ کہتے ہیں یہ دنیاوی زندگی کے سوا کچھ نہیں — ہم مرتے اور جیتے ہیں — اور ہمیں صرف زمانہ ہلاک کرتا ہے — اور ان کے پاس اس کی کوئی دلیل نہیں — وہ صرف ظن کرتے ہیں",
"""۱۔ دہریوں کا قول — و قالوا ما هي إلا حیاتنا الدنیا نموت و نحیا؛ و ما یهلکنا إلا الدهر؛ و ما لهم بذلک من علم؛ إن هم إلا یظنون۔
۲۔ ’’وَقَالُوا مَا هِيَ إِلَّا حَيَاتُنَا الدُّنْيَا نَمُوتُ وَنَحْيَا وَمَا يُهْلِكُنَا إِلَّا الدَّهْرُ وَمَا لَهُم بِذَٰلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا يَظُنُّونَ‘‘ — اور وہ کہتے ہیں یہ دنیاوی زندگی کے سوا کچھ نہیں — ہم مرتے اور جیتے ہیں — اور ہمیں صرف زمانہ ہلاک کرتا ہے — اور ان کے پاس اس کی کوئی دلیل نہیں — وہ صرف ظن کرتے ہیں — یعنی اور وہ کہتے ہیں یہ دنیاوی زندگی کے سوا کچھ نہیں ہم مرتے اور جیتے ہیں اور ہمیں صرف زمانہ ہلاک کرتا ہے اور ان کے پاس اس کی کوئی دلیل نہیں وہ صرف ظن کرتے ہیں۔
۳۔ عملی سبق: دہریانہ سوچ چھوڑو؛ آخرت پر ایمان لاؤ؛ اللہ سے ڈرو۔"""
),
4498: (
"اور جب ان پر ہماری روشن آیات تلاوت کی جاتی ہیں تو ان کی کوئی دلیل نہیں ہوتی سوائے اس کے کہ وہ کہیں ہمارے آباء کو لے آؤ اگر تم سچے ہو",
"""۱۔ بے دلیل چیلنج — و إذا تتلى علیهم آیاتنا بینات ما کان حجتهم إلا أن قالوا ائتوا بآبائنا إن کنتم صادقین۔
۲۔ ’’وَإِذَا تُتْلَىٰ عَلَيْهِمْ آيَاتُنَا بَيِّنَاتٍ مَّا كَانَ حُجَّتُهُمْ إِلَّا أَن قَالُوا ائْتُوا بِآبَائِنَا إِن كُنتُمْ صَادِقِينَ‘‘ —اور جب ان پر ہماری روشن آیات تلاوت کی جاتی ہیں تو ان کی کوئی دلیل نہیں ہوتی سوائے اس کے کہ وہ کہیں ہمارے آباء کو لے آؤ اگر تم سچے ہو۔
۳۔ عملی سبق: بے بنیاد چیلنج نہ دو؛ حق قبول کرو؛ اللہ سے ڈرو۔"""
),
4499: (
"کہہ دیجیے اللہ تمہیں زندگی دیتا ہے — پھر تمہیں موت دیتا ہے — پھر وہ تمہیں قیامت کے دن اکٹھا کرے گا جس میں کوئی شک نہیں — لیکن اکثر لوگ نہیں جانتے",
"""۱۔ زندگی و موت — قل اللہ یحییکم ثم یمیتکم ثم یجمعکم إلی یوم القیامۃ لا ریب فیہ؛ و لکن أکثر الناس لا یعلمون۔
۲۔ ’’قُلِ اللَّهُ يُحْيِيكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يَجْمَعُكُمْ إِلَىٰ يَوْمِ الْقِيَامَۃِ لَا رَيْبَ فِيهِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ‘‘ — کہہ دیجیے اللہ تمہیں زندگی دیتا ہے — پھر تمہیں موت دیتا ہے — پھر وہ تمہیں قیامت کے دن اکٹھا کرے گا جس میں کوئی شک نہیں — لیکن اکثر لوگ نہیں جانتے — یعنی کہہ دیجیے اللہ تمہیں زندگی دیتا ہے پھر تمہیں موت دیتا ہے پھر وہ تمہیں قیامت کے دن اکٹھا کرے گا جس میں کوئی شک نہیں لیکن اکثر لوگ نہیں جانتے۔
۳۔ عملی سبق: موت اور قیامت کو یاد رکھو؛ علم حاصل کرو؛ اللہ سے ڈرو۔"""
),
}
